{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Benazeprilat, which shares the benzazepinone diacid core with the query, had an absolute bioavailability of 27.1-28.5% when generated from oral benazepril, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Benazepril, the ethyl ester prodrug of the same benzazepinone ACE inhibitor scaffold, showed oral bioavailability of 28-37% in healthy volunteers, supporting high oral bioavailability for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Quinaprilat, another ACE inhibitor diacid, had an oral bioavailability of 46-52% when given as the prodrug quinapril, providing class-level evidence that such diacid ACE inhibitors can exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) based on the high-similarity benazeprilat absolute bioavailability of 27-28% and consistent ACE inhibitor diacid/prodrug oral bioavailability values; the more polar lysine-like side chain introduces uncertainty but does not overturn the class-level evidence.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "The effect of the primary amine/lysine-like side chain on intestinal absorption is inferred rather than experimentally measured.",
    "Most ACE inhibitor diacid bioavailability data come from prodrug administration rather than direct dosing of the diacid."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

